import{_ as n,o as a,c as i,ai as e}from"./chunks/framework.BxxKhjs3.js";const o=JSON.parse('{"title":"58-程序入口","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/58-程序入口/58-程序入口.md","filePath":"仓颉入门到实战/58-程序入口/58-程序入口.md","lastUpdated":1741483586000,"__rawMarkdown":"# 58-程序入口\\n\\n仓颉程序入口为 `main`，源文件根目录下的包的顶层最多只能有一个 `main`。\\n\\n如果模块采用生成可执行文件的编译方式，编译器只在源文件根目录下的顶层查找 `main`。如果没有找到，编译器将会报错；如果找到 `main`，编译器会进一步对其参数和返回值类型进行检查。需要注意的是，`main` 不可被访问修饰符修饰，当一个包被导入时，包中定义的 `main` 不会被导入。\\n\\n作为程序入口的 `main` 可以没有参数或参数类型为 `Array<String>`，返回值类型为 `Unit` 或整数类型。\\n\\n没有参数的 `main`：\\n\\n```typescript\\n// main.cj\\nmain(): Int64 { // Ok.\\n    return 0\\n}\\n```\\n\\n参数类型为 `Array<String>` 的 `main`：\\n\\n```typescript\\n// main.cj\\nmain(args: Array<String>): Unit { // Ok.\\n    for (arg in args) {\\n        println(arg)\\n    }\\n}\\n```\\n\\n使用 `cjc main.cj` 编译完成后，通过命令行执行：`./main Hello, World`，将会得到如下输出：\\n\\n```text\\nHello,\\nWorld\\n```\\n\\n以下是一些错误示例：\\n\\n```typescript\\n// main.cj\\nmain(): String { // Error, return type of \'main\' is not \'Integer\' or \'Unit\'.\\n    return \\"\\"\\n}\\n// main.cj\\nmain(args: Array<Int8>): Int64 { // Error, \'main\' cannot be defined with parameter whose type is not Array<String>.\\n    return 0\\n}\\n// main.cj\\n// Error, multiple \'main\'s are found in source files.\\nmain(args: Array<String>): Int32 {\\n    return 0\\n}\\n\\nmain(): Int8 {\\n    return 0\\n}\\n```"}'),p={name:"仓颉入门到实战/58-程序入口/58-程序入口.md"};function l(t,s,r,h,k,d){return a(),i("div",null,[...s[0]||(s[0]=[e("",12)])])}const g=n(p,[["render",l]]);export{o as __pageData,g as default};
